import{_ as o,C as e,o as l,c as n,j as i,E as t,a as s,a2 as d}from"./chunks/framework.C21TwvGF.js";const v=JSON.parse(`{"title":"1-hafta","description":"","frontmatter":{"title":"1-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (Python)","link":"/10-sinf-python/"},"n":1,"bob":"I-bob · Django REST freymvork","lessons":[{"g":1,"title":"Django REST Framework. Server side rendering va user side rendering tushunchalari","lead":"Veb-dasturlashda frontend va backend o'rtasidagi aloqa qanday o'rnatiladi? Ushbu darsda biz serverda HTML tayyorlash (SSR) va brauzerda ma'lumotlarni dinamik chizish (CSR/USR) modellarini tahlil qilamiz hamda Django REST Framework dunyosiga ilk qadamni qo'yamiz.","link":"/10-sinf-python/hafta-01/dars-1","slide":"/slaydlar/10-sinf-python/hafta-01/dars-1.html","test":"/slaydlar/10-sinf-python/hafta-01/dars-1-test.html"},{"g":2,"title":"DRF loyiha qurish: MBni loyihalash. Loyihani yaratish, dastlabki sozlamalar","lead":"Yirik va jiddiy backend loyihalari mustahkam poydevordan boshlanadi. Ushbu darsda biz real NewsPortal (yangiliklar portali) loyihasi uchun ma'lumotlar bazasini loyihalashtiramiz, Python virtual muhitini sozlaymiz va xalqaro clean architecture standartlariga mos Django loyihasini noldan quramiz.","link":"/10-sinf-python/hafta-01/dars-2","slide":"/slaydlar/10-sinf-python/hafta-01/dars-2.html","test":"/slaydlar/10-sinf-python/hafta-01/dars-2-test.html"},{"g":3,"title":"Model, View va Serializer. Routerlar","lead":"Django REST Framework ning yuragi — bu Model, Serializer, View va Router komponentlarining o'zaro mukammal uyg'unligidir. Ushbu darsda biz NewsPortal tizimining to'liq ishlaydigan dastlabki REST API endpointlarini quramiz va N+1 muammosini hal etishni o'rganamiz.","link":"/10-sinf-python/hafta-01/dars-3","slide":"/slaydlar/10-sinf-python/hafta-01/dars-3.html","test":"/slaydlar/10-sinf-python/hafta-01/dars-3-test.html"}],"test":"/slaydlar/10-sinf-python/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-python/hafta-01/index.md","filePath":"10-sinf-python/hafta-01/index.md"}`),h={name:"10-sinf-python/hafta-01/index.md"},y={class:"blk"},m={id:"uyga-vazifa",tabindex:"-1"};function g(c,a,u,f,b,k){const r=e("Icon");return l(),n("div",null,[i("div",y,[i("h2",m,[t(r,{name:"house"}),a[0]||(a[0]=s(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Ushbu haftada o&#39;tilgan darslar bo&#39;yicha uyga vazifalar ro&#39;yxati:</p><hr><h3 id="_1-dars-django-rest-framework-ssr-va-usr-tushunchalari" tabindex="-1">1-dars. Django REST Framework. SSR va USR tushunchalari <a class="header-anchor" href="#_1-dars-django-rest-framework-ssr-va-usr-tushunchalari" aria-label="Permalink to &quot;1-dars. Django REST Framework. SSR va USR tushunchalari&quot;">​</a></h3><ol><li>Konspektdagi SSR va USR taqqoslash jadvalini daftaringizga ko&#39;chirib, har bir mezonni o&#39;z so&#39;zlaringiz bilan izohlang.</li><li>Internetdagi o&#39;zingiz yoqtirgan bitta veb-saytni tanlang (masalan, yangiliklar yoki ijtimoiy tarmoq), brauzerda <code>F12</code> (Dasturchi asboblari) tugmasini bosing, <code>Network</code> (Tarmoq) bo&#39;limini oching va sahifa yuklanishida qanday <code>.html</code> va qanday <code>.json</code> so&#39;rovlar o&#39;tayotganini kuzating. Natijalarni daftarga 3-4 jumla bilan qayd eting.</li><li>Keyingi darsda o&#39;rnatiladigan Django va DRF paketlari uchun kompyuteringizda Python versiyasini terminalda <code>python --version</code> orqali tekshirib qo&#39;ying.</li></ol><hr><h3 id="_2-dars-drf-loyiha-qurish-mbni-loyihalash-loyihani-yaratish-dastlabki-sozlamalar" tabindex="-1">2-dars. DRF loyiha qurish: MBni loyihalash. Loyihani yaratish, dastlabki sozlamalar <a class="header-anchor" href="#_2-dars-drf-loyiha-qurish-mbni-loyihalash-loyihani-yaratish-dastlabki-sozlamalar" aria-label="Permalink to &quot;2-dars. DRF loyiha qurish: MBni loyihalash. Loyihani yaratish, dastlabki sozlamalar&quot;">​</a></h3><ol><li>Konspektdagi terminal buyruqlarini kompyuteringizda ketma-ket bajarib, <code>newsportal</code> loyihasini yarating.</li><li><code>src/config/settings/base.py</code> faylini konspektdagi namuna asosida shakllantiring va <code>INSTALLED_APPS</code> ga <code>&#39;rest_framework&#39;</code> qo&#39;shing.</li><li>Loyiha ildizida <code>.env</code> faylini yarating va unga <code>SECRET_KEY</code> kiriting.</li><li>Terminalda <code>python manage.py migrate</code> buyrug&#39;ini bering va barcha dastlabki jadvallar bazaga yozilganligini tekshiring.</li></ol><hr><h3 id="_3-dars-model-view-va-serializer-routerlar" tabindex="-1">3-dars. Model, View va Serializer. Routerlar <a class="header-anchor" href="#_3-dars-model-view-va-serializer-routerlar" aria-label="Permalink to &quot;3-dars. Model, View va Serializer. Routerlar&quot;">​</a></h3><ol><li>Konspektdagi <code>CategorySerializer</code>, <code>TagSerializer</code> va <code>PostListSerializer</code> kodlarini o&#39;z loyihangizda yozing.</li><li><code>apps/news/views.py</code> da <code>CategoryViewSet</code> va <code>PostViewSet</code> ni yarating, ularni <code>DefaultRouter</code> orqali <code>config/urls.py</code> ga ulang.</li><li>Serverni ishga tushirib, brauzer orqali <code>http://127.0.0.1:8000/api/v1/posts/</code> manzilini oching va Browsable API yordamida kamida 2 ta kategoriya va 3 ta yangilik yarating.</li></ol><hr>',11))])])}const p=o(h,[["render",g]]);export{v as __pageData,p as default};
